<script setup lang="ts">
import {computed,ref} from 'vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiSelectField from '@/components/ui/UiSelectField.vue'
import type {RefV2} from '@/features/models/api-v2'
import type {PreviewV2,ObjectEntryV2,CatalogV2,ScopeRequestV2} from './api-v2'
const props=defineProps<{open:boolean;preview:PreviewV2|null;entries?:readonly ObjectEntryV2[];busy?:boolean;error?:string;stale?:boolean;workspace?:boolean;catalog?:CatalogV2|null;scope?:ScopeRequestV2;loading?:boolean;scopeError?:string;hasResult?:boolean}>()
const emit=defineEmits<{close:[];direction:[value:'upload'|'download'];backup:[value:boolean];confirm:[];retry:[];catalog:[read:string|null,write:string|null];prepare:[read:string|null,write:string|null];toggle:[entry:ObjectEntryV2,value:boolean];mcp:[name:string,client:string];subset:[channelId:string,kind:'all'|'models'|'families',ids:string[]];option:[channelId:string,field:'includeConnection'|'includeKey'|'includeAuthorization',value:boolean];credential:[entry:ObjectEntryV2,value:boolean];review:[value:boolean];result:[];recovery:[];connection:[];revision:[reference:RefV2,value:boolean];default:[reference:RefV2,value:boolean];global:[value:boolean]}>()
const search=ref(''),readPassphrase=ref(''),writePassphrase=ref(''),useProtection=ref(false)
const shown=computed(()=>props.catalog?.entries.filter(e=>(e.label+' '+e.id).toLowerCase().includes(search.value.toLowerCase()))??[])
function selected(entry:ObjectEntryV2){const s=props.scope?.selection;if(!s)return false;switch(entry.kind){case'channel':return s.channels.some(c=>c.portableChannelId===entry.id);case'template':return s.templateRefs.some(r=>r.templateId===entry.id);case'preferences':return s.manager.preferences;case'extensions':return s.manager.extensions;case'account':return s.manager.accountIds.includes(entry.id);case'skill':return s.skillNames.includes(entry.id);case'mcp':return s.mcpSources.some(m=>m.name===entry.id)}}
function channel(id:string){return props.scope?.selection.channels.find(c=>c.portableChannelId===id)}
function subset(entry:ObjectEntryV2,kind:'all'|'models'|'families'){emit('subset',entry.id,kind,kind==='models'?[...entry.modelIds]:kind==='families'?[...entry.familyIds]:[])}
function toggleSubset(entry:ObjectEntryV2,kind:'models'|'families',id:string,value:boolean){const chosen=kind==='models'?channel(entry.id)?.modelIds:channel(entry.id)?.familyIds;const ids=(chosen??[]).filter(n=>n!==id);if(value)ids.push(id);emit('subset',entry.id,kind,ids)}
const kinds={channel:'渠道与模型',template:'模型模版',preferences:'管理器偏好',extensions:'扩展配置',account:'账户信息',skill:'Skill',mcp:'MCP'}
function submit(kind:'catalog'|'prepare'){const read=readPassphrase.value||null,write=useProtection.value?(writePassphrase.value||null):null;if(kind==='prepare')emit('prepare',read,write);else emit('catalog',read,write);readPassphrase.value='';writePassphrase.value=''}
const initialization=computed(()=>props.preview?.plan.kind==='upload'&&props.preview.plan.plan.initialization==='on_confirm')
const disabled=computed(()=>!!props.busy||!!props.error||!!props.stale||!props.preview||props.preview.noChange||props.preview.plan.kind==='no_change'||props.preview.entries.some(e=>e.status==='unavailable'||e.status==='source_required'))
const actionLabel=computed(()=>initialization.value?'初始化并上传':props.preview?.chosenDirection==='download'?'确认下载':'确认上传')
function savedTime(value:string|null|undefined){return value&&Number.isFinite(Date.parse(value))?value:'未知'}
function label(kind:string,id:string){return props.entries?.find(e=>e.kind===kind&&e.id===id)?.label??id}
const changes={add:'新增',update:'更新',unchanged:'不变',unavailable:'来源暂不可用',source_required:'需要明确来源'}
const reasonText={same_semantic_content:'所选内容一致，无需更新。',both_empty:'两侧均没有所选内容。',cloud_empty:'已核实云端暂无有效配置，默认上传。',local_empty:'本机暂无所选内容，云端有效配置可下载。',local_saved_later:'按可靠业务保存时间预选上传。',cloud_saved_later:'按可靠业务保存时间预选下载。',unreliable_save_time:'保存时间不足以判新；云端有有效配置，默认下载。',equal_time_different_content:'业务保存时间相同但内容不同；按本次明确方向预览。',explicit_upload:'本次明确以上传来源预览。',explicit_download:'本次明确以下载来源预览。'}
</script>
<template>
  <section v-if="workspace" class="config-sync-workspace-v2" aria-label="WebDAV配置同步">
    <div class="sync-workspace-toolbar"><div><h2>配置同步</h2><p>先预览所选配置的来源与真实变化，确认后更新。</p></div><div><UiButton :disabled="loading||busy" @click="submit('catalog')">重新读取目录</UiButton><UiButton :disabled="busy" @click="emit('connection')">连接设置</UiButton><UiButton v-if="hasResult" @click="emit('result')">查看原操作</UiButton></div></div>
    <p v-if="loading" role="status">正在读取有效配置目录…</p><p v-if="error&&!open" class="model-error" role="alert">{{error}}</p><p v-if="scopeError" class="model-error" role="alert">{{scopeError}}</p>
    <p v-if="catalog&&['conflict','initialization_ambiguous'].includes(catalog.cloudState)" class="model-error" role="alert">{{catalog.cloudState==='conflict'?'云端有并发提交，须明确选择来源后预览。':'多个初始化代次，普通写入已停止。'}}<UiButton size="sm" @click="emit('recovery')">查看恢复动作</UiButton></p>
    <label>搜索范围<input v-model="search" class="input" type="search" aria-label="搜索同步对象" /></label>
    <div v-if="catalog" class="sync-scope-list"><article v-for="entry in shown" :key="entry.kind+entry.id"><div class="sync-scope-heading"><label><input type="checkbox" :aria-label="'同步 '+entry.label" :checked="selected(entry)" :disabled="busy||loading" @change="emit('toggle',entry,($event.target as HTMLInputElement).checked)" /><strong>{{entry.label}}</strong><span>{{kinds[entry.kind]}}</span></label><span>{{entry.availableLocal?'本机可读':''}}{{entry.availableLocal&&entry.availableCloud?' / ':''}}{{entry.availableCloud?'云端可读':''}}</span></div>
      <template v-if="entry.kind==='channel'&&selected(entry)"><div class="sync-workspace-options"><UiSelectField :model-value="channel(entry.id)?.modelIds!==null?'models':channel(entry.id)?.familyIds!==null?'families':'all'" :label="entry.label+'模型范围'" :disabled="busy" :options="[{value:'all',label:'全渠道模型'},{value:'models',label:'逐模型选择'},{value:'families',label:'按模型族片段'}]" @update:model-value="subset(entry,$event as 'all'|'models'|'families')" /><label><input type="checkbox" :checked="channel(entry.id)?.includeConnection" :disabled="busy||channel(entry.id)?.familyIds!==null" @change="emit('option',entry.id,'includeConnection',($event.target as HTMLInputElement).checked)" />包含连接</label><label><input type="checkbox" :checked="channel(entry.id)?.includeKey" :disabled="busy||!entry.secretAvailable||channel(entry.id)?.familyIds!==null" @change="emit('option',entry.id,'includeKey',($event.target as HTMLInputElement).checked)" />包含 Key</label><label><input type="checkbox" :checked="channel(entry.id)?.includeAuthorization" :disabled="busy||!entry.secretAvailable||channel(entry.id)?.familyIds!==null" @change="emit('option',entry.id,'includeAuthorization',($event.target as HTMLInputElement).checked)" />包含受支持授权</label></div>
      <div v-if="channel(entry.id)?.modelIds!==null" class="sync-model-subset"><label v-for="model in entry.models" :key="model.rawModelId"><input type="checkbox" :checked="channel(entry.id)?.modelIds?.includes(model.rawModelId)" :disabled="busy" @change="toggleSubset(entry,'models',model.rawModelId,($event.target as HTMLInputElement).checked)" />{{model.label||model.rawModelId}}<code>{{model.rawModelId}}</code></label></div>
      <div v-if="channel(entry.id)?.familyIds!==null" class="sync-model-subset"><label v-for="family in entry.familyIds" :key="family"><input type="checkbox" :checked="channel(entry.id)?.familyIds?.includes(family)" :disabled="busy" @change="toggleSubset(entry,'families',family,($event.target as HTMLInputElement).checked)" />{{family}}</label></div></template>
      <template v-if="entry.kind==='mcp'"><UiSelectField :model-value="scope?.mcpClients[entry.id]??''" :label="entry.label+'定义来源'" :disabled="busy" :options="[{value:'',label:'请选择明确来源 / 暂不同步'},...(catalog.mcpSources.find(m=>m.name===entry.id)?.sources??[]).map(s=>({value:s.source,label:s.source}))]" @update:model-value="emit('mcp',entry.id,$event)" /><p v-if="catalog.mcpSources.find(m=>m.name===entry.id)?.differingFields.length" class="model-error">各客户端同名定义不同，请明确采用来源。差异字段：{{catalog.mcpSources.find(m=>m.name===entry.id)?.differingFields.join('、')}}</p></template>
      <label v-if="(entry.kind==='skill'||entry.kind==='mcp')&&selected(entry)"><input type="checkbox" :checked="entry.kind==='skill'?scope?.selection.extensionCredentials.skillNames.includes(entry.id):scope?.selection.extensionCredentials.mcpNames.includes(entry.id)" :disabled="busy||!entry.secretAvailable" @change="emit('credential',entry,($event.target as HTMLInputElement).checked)" />包含该项所选凭据</label>
      <details v-if="entry.kind==='template'&&selected(entry)"><summary>选择确切保存版本 · {{scope?.selection.templateRefs.filter(r=>r.templateId===entry.id).length??0}} 个</summary><div v-for="reference in entry.revisions" :key="reference.revisionId"><label><input type="checkbox" :checked="scope?.selection.templateRefs.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId&&r.digest===reference.digest)" :disabled="busy" @change="emit('revision',reference,($event.target as HTMLInputElement).checked)" />{{reference.revisionId}}</label><label><input type="checkbox" :checked="scope?.selection.adoptTemplateDefaults.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId)" :disabled="busy||!scope?.selection.templateRefs.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId)" @change="emit('default',reference,($event.target as HTMLInputElement).checked)" />明确采用此保存版本为默认</label></div><p>未保存编辑不进入普通同步；不取任意 latest，精确依赖由后端补齐核验。</p></details>
    </article></div>
    <p v-if="catalog&&!shown.length">当前筛选下没有对象；无本机对象不阻止核验有效云端配置。</p>
    <label><input type="checkbox" :checked="scope?.selection.includeGlobalTemplateRefs" :disabled="busy" @change="emit('global',($event.target as HTMLInputElement).checked)" />包含全局精确模版候选引用</label>
    <label><input type="checkbox" :checked="scope?.assetsReviewed" :disabled="busy" @change="emit('review',($event.target as HTMLInputElement).checked)" />已核对所选扩展与 MCP 来源范围</label>
    <details><summary>受保护配置的本次口令</summary><label>读取云端口令<input v-model="readPassphrase" class="input" type="password" autocomplete="off" aria-label="读取云端口令" /></label><label><input v-model="useProtection" type="checkbox" />本次上传启用保护</label><label v-if="useProtection">写入保护口令<input v-model="writePassphrase" class="input" type="password" autocomplete="new-password" aria-label="写入保护口令" /></label><p>口令仅传本次服务会话，不进入范围偏好或日志。</p></details>
    <div class="sync-workspace-footer"><UiButton variant="primary" :disabled="loading||busy||!catalog||catalog.cloudState==='initialization_ambiguous'" @click="submit('prepare')">同步</UiButton></div>
  </section>
  <UiDialog v-if="!workspace&&open" :open="open" title="同步预览" wide panel-class="config-sync-preview-v2" @close="emit('close')">
    <p v-if="busy" role="status">正在读取所选配置并计算变化，确认暂不可用。</p><p v-if="error" class="model-error" role="alert">{{error}}</p><p v-if="stale" class="model-error" role="alert">来源、范围、端点或内容已变化，请重新预览；旧确认保持失效。</p>
    <template v-if="preview">
      <dl class="sync-preview-facts"><dt>本次来源</dt><dd><UiSelectField :model-value="preview.chosenDirection==='download'?'download':'upload'" label="本次同步来源" :disabled="busy" :options="[{value:'upload',label:'本机配置 → 云端（上传）'},{value:'download',label:'云端配置 → 本机（下载）'}]" @update:model-value="emit('direction',$event as 'upload'|'download')" /></dd><dt>本机保存时间</dt><dd>{{savedTime(preview.localSavedTime)}}</dd><dt>云端保存时间</dt><dd>{{savedTime(preview.cloudSavedTime)}}</dd></dl>
      <p role="status">{{reasonText[preview.automaticReason]}}</p>
      <p v-if="initialization">此目录尚未初始化。确认后才创建本次初始化代次并上传所选配置；预览、切换来源和取消不会写云端。</p>
      <label v-if="preview.chosenDirection==='download'&&!preview.noChange" class="sync-backup"><input type="checkbox" :checked="preview.backupBeforeUpdate" :disabled="busy" @change="emit('backup',($event.target as HTMLInputElement).checked)" />更新前备份</label>
      <h3>本次变化 · {{preview.entries.length}} 项</h3><ul class="sync-preview-diffs"><li v-for="entry in preview.entries" :key="entry.kind+entry.id"><strong>{{label(entry.kind,entry.id)}}</strong><span>{{changes[entry.status]}}</span></li></ul>
      <p v-if="preview.noChange||preview.plan.kind==='no_change'">所选内容没有需要写入的变化，不创建业务写入、备份或远端提交。</p>
      <p>只更新已确认所选范围，未选对象和凭据保持。下载确认时会结束未修改的模型编辑会话，有未保存输入时将停止。切换来源将重新只读 prepare，不直接执行。</p>
    </template>
    <template #actions="{close}"><UiButton @click="close">取消</UiButton><UiButton v-if="error||stale" :disabled="busy" @click="emit('retry')">重新预览</UiButton><UiButton variant="primary" :disabled="disabled" :loading="busy" @click="emit('confirm')">{{actionLabel}}</UiButton></template>
  </UiDialog>
</template>
<style scoped>
.config-sync-workspace-v2{display:grid;gap:16px;min-width:0}.sync-workspace-toolbar,.sync-workspace-toolbar>div:last-child,.sync-scope-heading,.sync-workspace-options{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.config-sync-workspace-v2 label{display:flex;align-items:center;gap:8px;min-width:0}.config-sync-workspace-v2 input[type=search],.config-sync-workspace-v2 input[type=password]{min-width:0;max-width:100%}.sync-scope-list>article{display:grid;gap:12px;padding:14px 0;border-bottom:1px solid var(--border)}.sync-scope-heading>span,.sync-scope-heading label>span{color:var(--muted)}.sync-model-subset{max-height:240px;overflow:auto;display:grid;gap:8px}.sync-model-subset code{overflow-wrap:anywhere}.config-sync-workspace-v2 details p{overflow-wrap:anywhere}.sync-workspace-footer{display:flex;justify-content:flex-end}.config-sync-workspace-v2 h2{font-size:var(--text-subtitle);margin:0}.config-sync-workspace-v2 h2+p{margin-bottom:0;color:var(--muted)}
.sync-preview-facts{display:grid;grid-template-columns:100px minmax(0,1fr);gap:10px 16px}.sync-preview-facts dt{color:var(--muted)}.sync-preview-facts dd{margin:0;overflow-wrap:anywhere}.sync-preview-diffs{list-style:none;padding:0;margin:0}.sync-preview-diffs li{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--border)}.sync-preview-diffs strong{overflow-wrap:anywhere;min-width:0;font-weight:var(--weight-medium)}.sync-preview-diffs span{flex:none;color:var(--muted)}.sync-backup{display:flex;align-items:center;gap:8px}.model-error{color:var(--red)}p{line-height:1.6}h3{font-size:var(--text-body)}@media(max-width:560px){.sync-preview-facts{grid-template-columns:minmax(0,1fr)}}
</style>
